import openpyxl
wb = openpyxl.load_workbook('seed_collection_0006_incorrect_sign_2291_input.xlsx', data_only=False)
unit_sheets = ['NNG','TW','Citrus','NB','GCO_HPL','ETS OPS-EOTT','Other']
# build dict coordinate -> {sheet: formula}
coords = {}
for name in unit_sheets:
    ws = wb[name]
    for row in ws.iter_rows():
        for cell in row:
            if isinstance(cell.value, str) and cell.value.startswith('='):
                coords.setdefault(cell.coordinate, {})[name] = cell.value

# find coordinates where formulas differ across sheets
for coord in sorted(coords, key=lambda c:(int(''.join(filter(str.isdigit,c))), c)):
    d = coords[coord]
    vals = set(d.values())
    if len(vals) > 1:
        print(coord, "->")
        for k,v in sorted(d.items()):
            print(f"   {k}: {v}")
